mapper.select:
SELECT a.PLO_NUM,a.PLO_NAME,a.DEPT_NUM,a.DEPT_GROUP, nvl( b.HANDLE_DATE, '未报名' ) AS SIGN_DATE, nvl( c.STUDY_DATE, '无记录' ) STUDY_DATE, nvl( c.COIN, 0 ) COIN, nvl( c.HOURS, 0 ) HOURS, CASE WHEN c.STUDY_COMP = 1 THEN '完成' WHEN c.STUDY_COMP = 0 THEN '未完成' ELSE '未开始' END STUDY_COMP, CASE WHEN c.EVAL_COMP = 1 THEN '完成' WHEN c.EVAL_COMP = 0 THEN '未完成' ELSE '未开始' END EVAL_COMP, CASE WHEN c.EXAM_COMP = 1 THEN '通过' WHEN c.EXAM_COMP = 0 THEN '不通过' ELSE '未开始' END EXAM_COMP, CASE WHEN c.IF_EVAL = 1 THEN '需要' WHEN c.IF_EVAL = 0 THEN '无需' ELSE '未记录' END IF_EVAL, CASE WHEN c.IF_EXAM = 1 THEN '需要' WHEN c.IF_EXAM = 0 THEN '无需' ELSE '未记录' END IF_EXAM, CASE WHEN c.COURSE_PASS = 1 THEN '完成-通过' WHEN c.COURSE_PASS = 0 THEN '完成-不通过' WHEN c.COURSE_PASS = 2 THEN '进行中' ELSE '未开始' END COURSE_PASS, c.EVAL_DATE, c.COMP_DATE, nvl( d.CURR_TIME, 0 ) CURR_TIME, nvl( e.TOTAL_TIME, 0 ) TOTAL_TIME FROM (SELECT DEPT_NUM,DEPT_GROUP,PLO_NUM,PLO_NAME FROM CUS_EMP_INFO WHERE job_level between '100' and '110' AND PLO_STATUS = '00' AND DEPT_GROUP IS NOT NULL
and (DEPT_GROUP = #{ deptNum, jdbcType = VARCHAR } or DEPT_NUM = #{ deptNum, jdbcType = VARCHAR })
) a LEFT JOIN ( SELECT PLO_NUM, COURSE_ID, HANDLE_DATE, STATUS FROM trm_course_sign WHERE COURSE_ID = #{ courseId, jdbcType = VARCHAR } ) b ON ( a.PLO_NUM = b.PLO_NUM ) LEFT JOIN ( SELECT * FROM TRM_STUDY_LOG WHERE COURSE_ID = #{ courseId, jdbcType = VARCHAR } ) c ON ( a.PLO_NUM = c.PLO_NUM ) LEFT JOIN ( SELECT PLO_NUM, sum( CURR_TIME ) AS CURR_TIME FROM TRM_LEARN_PROG WHERE COURSE_ID = #{ courseId, jdbcType = VARCHAR } GROUP BY PLO_NUM ) d ON ( a.PLO_NUM = d.PLO_NUM ) LEFT JOIN ( SELECT sum( DURATION ) AS TOTAL_TIME FROM TRM_COURSE_FILE WHERE COURSE_ID = #{ courseId, jdbcType = VARCHAR } ) e ON (1 = 1) order by a.DEPT_NUM,a.DEPT_GROUP
